INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 62, "2025/01/31 12:00:00", 1000001, 0.0, 1, "2030/01/01 14:59:59", 1, "カリン", 3.414, 2, -416.5, 190805);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, "ミッションをクリアして、\n報酬をゲットしましょう！", 62, "2025/01/31 12:00:00", 1000002, 0.0, 1, "2030/01/01 14:59:59", 2, "カリン", 3.099, 2, -416.5, 190805);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, "受け取ることができる\n報酬があるようです\n確認してみてください", 63, "2025/01/31 12:00:00", 1000003, 0.0, 1, "2030/01/01 14:59:59", 3, "カリン", 2.801, 2, -416.5, 190805);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, "報酬がもらえますよ！\nチェックしてみてください", 63, "2025/01/31 12:00:00", 1000004, 0.0, 2, "2030/01/01 14:59:59", 4, "カリン", 0.0, 2, -416.5, 190805);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 64, "2025/01/31 12:00:00", 1000005, 0.0, 2, "2030/01/01 14:59:59", 5, "カリン", 2.12, 1, -363.0, 190805);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 64, "2025/01/31 12:00:00", 1000006, 0.0, 1, "2030/01/01 14:59:59", 6, "カリン", 1.68, 2, -363.0, 190805);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 64, "2025/01/31 12:00:00", 1000007, 0.0, 2, "2030/01/01 14:59:59", 7, "カリン", 2.33, 1, -363.0, 190805);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10201, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 61, "2025/01/31 12:00:00", 1020101, -6.0, 3, "2030/01/01 14:59:59", 101, "ラビリスタ", 5.18, 7, -285.0, 133701);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10201, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 61, "2025/01/31 12:00:00", 1020102, -2.0, 1, "2030/01/01 14:59:59", 201, "クリスティーナ", 8.77, 2, -285.0, 133901);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10201, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 61, "2025/01/31 12:00:00", 1020103, 0.0, 6, "2030/01/01 14:59:59", 301, "ネネカ", 15.5, 1, -285.0, 133801);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10202, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 61, "2025/02/28 12:00:00", 1020201, 0.0, 2, "2030/01/01 14:59:59", 101, "ランファ", 9.061, 5, -285.0, 134301);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10202, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 61, "2025/02/28 12:00:00", 1020202, 0.0, 1, "2030/01/01 14:59:59", 201, "チカ", 7.699, 2, -285.0, 134401);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10203, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 61, "2025/03/31 12:00:00", 1020301, 0.0, 1, "2030/01/01 14:59:59", 101, "アオイ", 8.595, 2, -285.0, 134601);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10203, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 61, "2025/03/31 12:00:00", 1020302, 0.0, 1, "2030/01/01 14:59:59", 201, "クローチェ", 7.758, 2, -285.0, 134501);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10204, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 61, "2025/04/30 12:00:00", 1020401, 0.0, 2, "2030/01/01 14:59:59", 101, "ルイズマリー", 7.0, 6, -285.0, 132302);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10204, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 61, "2025/04/30 12:00:00", 1020402, 0.0, 1, "2030/01/01 14:59:59", 201, "イロハ", 7.904, 2, -285.0, 132402);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10204, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 61, "2025/04/30 12:00:00", 1020403, 0.0, 4, "2030/01/01 14:59:59", 301, "ソノ", 8.487, 2, -285.0, 132502);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10205, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 61, "2025/05/31 12:00:00", 1020502, 0.0, 1, "2030/01/01 14:59:59", 101, "カノン", 8.763, 2, -285.0, 134901);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10205, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 61, "2025/05/31 12:00:00", 1020503, 0.0, 1, "2030/01/01 14:59:59", 201, "ツムギ", 6.417, 3, -285.0, 134801);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10206, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 61, "2025/06/30 12:00:00", 1020601, 0.0, 3, "2030/01/01 14:59:59", 101, "エリス", 10.335, 7, -285.0, 135001);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10206, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 61, "2025/06/30 12:00:00", 1020602, 0.0, 2, "2030/01/01 14:59:59", 201, "シェフィ", 6.281, 4, -285.0, 135101);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10206, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 61, "2025/06/30 12:00:00", 1020603, 0.0, 1, "2030/01/01 14:59:59", 301, "プレシア", 12.244, 2, -285.0, 135201);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10207, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 61, "2025/07/31 12:00:00", 1020701, 0.0, 2, "2030/01/01 14:59:59", 101, "クリア", 6.339, 8, -285.0, 135301);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10207, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 61, "2025/07/31 12:00:00", 1020702, 0.0, 7, "2030/01/01 14:59:59", 201, "アネモネ", 8.184, 9, -285.0, 135401);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10208, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 61, "2025/08/31 12:00:00", 1020801, 0.0, 9, "2030/01/01 14:59:59", 101, "アイラ", 3.906, 2, -285.0, 129101);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10208, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 61, "2025/08/31 12:00:00", 1020802, 0.0, 1, "2030/01/01 14:59:59", 201, "シナツ", 14.465, 2, -285.0, 129201);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10208, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 61, "2025/08/31 12:00:00", 1020803, 0.0, 4, "2030/01/01 14:59:59", 301, "ヒヨリ", 8.662, 3, -285.0, 100101);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10208, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 61, "2025/08/31 12:00:00", 1020804, 0.0, 1, "2030/01/01 14:59:59", 401, "レイ", 10.915, 3, -285.0, 100301);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10209, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 61, "2025/09/30 12:00:00", 1020901, 0.0, 1, "2030/01/01 14:59:59", 101, "ユキノ", 6.042, 7, -285.0, 135802);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10209, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 61, "2025/09/30 12:00:00", 1020902, 0.0, 4, "2030/01/01 14:59:59", 201, "サツキ", 9.402, 1, -285.0, 135903);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10209, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 61, "2025/09/30 12:00:00", 1020903, 0.0, 8, "2030/01/01 14:59:59", 301, "ルルィ", 8.16, 1, -285.0, 136902);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10210, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 61, "2025/10/31 12:00:00", 1021001, 0.0, 3, "2030/01/01 14:59:59", 101, "カスミ", 5.0, 2, -285.0, 137401);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10210, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 61, "2025/10/31 12:00:00", 1021002, 0.0, 4, "2030/01/01 14:59:59", 201, "アラクネ", 8.12, 1, -285.0, 136001);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10210, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 61, "2025/10/31 12:00:00", 1021003, 0.0, 4, "2030/01/01 14:59:59", 301, "ナーナ", 6.386, 2, -285.0, 136202);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10211, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 61, "2025/11/30 12:00:00", 1021101, 0.0, 3, "2030/01/01 14:59:59", 101, "ユイ", 7.438, 4, -285.0, 136402);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10211, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 61, "2025/11/30 12:00:00", 1021102, 0.0, 1, "2030/01/01 14:59:59", 201, "ミソラ", 8.35, 5, -285.0, 136302);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10212, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 61, "2025/12/31 12:00:00", 1021201, 0.0, 1, "2030/01/01 14:59:59", 101, "シズル", 5.0, 2, -285.0, 136501);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10212, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 61, "2025/12/31 12:00:00", 1021202, 0.0, 1, "2030/01/01 14:59:59", 201, "リノ", 5.25, 2, -285.0, 137902);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10212, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 61, "2025/12/31 12:00:00", 1021203, 0.0, 1, "2030/01/01 14:59:59", 301, "ラビリスタ", 7.5, 2, -285.0, 106801);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10213, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 61, "2026/01/31 12:00:00", 1021301, 0.0, 1, "2030/01/01 14:59:59", 101, "ライラエル", 8.204, 2, -285.0, 126501);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10213, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 61, "2026/01/31 12:00:00", 1021302, 0.0, 1, "2030/01/01 14:59:59", 201, "ネフィ＝ネラ", 7.176, 2, -285.0, 129701);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10213, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 61, "2026/01/31 12:00:00", 1021303, 0.0, 1, "2030/01/01 14:59:59", 301, "ヴァイオレット", 8.602, 5, -285.0, 133101);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10213, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 61, "2026/02/06 12:00:00", 1021304, 0.0, 1, "2030/01/01 14:59:59", 102, "ライラエル", 10.14, 3, -285.0, 138101);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10213, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 61, "2026/02/06 12:00:00", 1021305, 0.0, 1, "2030/01/01 14:59:59", 202, "ネフィ＝ネラ", 10.152, 7, -285.0, 138201);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10213, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 61, "2026/02/06 12:00:00", 1021306, 0.0, 4, "2030/01/01 14:59:59", 302, "ヴァイオレット", 9.688, 3, -285.0, 138001);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10213, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 61, "2026/02/12 12:00:00", 1021307, 0.0, 2, "2030/01/01 14:59:59", 401, "ペコリーヌ", 5.928, 1, -285.0, 138301);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10214, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 61, "2026/02/28 12:00:00", 1021401, 0.0, 4, "2030/01/01 14:59:59", 101, "ワカナ", 9.19, 2, -285.0, 138702);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10214, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 61, "2026/02/28 12:00:00", 1021402, 0.0, 1, "2030/01/01 14:59:59", 201, "シオリ", 8.724, 3, -285.0, 138802);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10215, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 61, "2026/03/31 12:00:00", 1021501, 0.0, 4, "2030/01/01 14:59:59", 101, "グレイス", 7.758, 1, -285.0, 138902);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10215, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 61, "2026/03/31 12:00:00", 1021502, 0.0, 6, "2030/01/01 14:59:59", 201, "キョウカ", 6.375, 4, -285.0, 139002);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10215, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 61, "2026/03/31 12:00:00", 1021503, 0.0, 6, "2030/01/01 14:59:59", 301, "ルルィ", 6.173, 1, -285.0, 136902);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10216, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 61, "2026/04/30 12:00:00", 1021601, 0.0, 6, "2030/01/01 14:59:59", 101, "ミホ", 4.202, 2, -285.0, 139202);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10216, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 61, "2026/04/30 12:00:00", 1021602, 0.0, 6, "2030/01/01 14:59:59", 201, "マホ", 2.842, 1, -285.0, 139302);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10216, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 61, "2026/04/30 12:00:00", 1021603, 0.0, 4, "2030/01/01 14:59:59", 301, "エリカ", 4.598, 1, -285.0, 139402);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10217, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 61, "2026/05/31 12:00:00", 1021701, 0.0, 4, "2030/01/01 14:59:59", 101, "リリ", 6.533, 3, -285.0, 125802);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10217, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 61, "2026/05/31 12:00:00", 1021702, 0.0, 3, "2030/01/01 14:59:59", 301, "プレシア", 5.0, 3, -285.0, 126102);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10217, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 61, "2026/05/31 12:00:00", 1021703, 0.0, 3, "2030/01/01 14:59:59", 201, "クリア", 5.214, 4, -285.0, 126002);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10217, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 61, "2026/05/31 12:00:00", 1021704, 0.0, 1, "2030/01/01 14:59:59", 102, "リリ", 8.781, 3, -285.0, 139501);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10217, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 61, "2026/05/31 12:00:00", 1021705, 0.0, 2, "2030/01/01 14:59:59", 202, "クリア", 6.529, 1, -285.0, 139601);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10217, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 61, "2026/05/31 12:00:00", 1021706, 0.0, 3, "2030/01/01 14:59:59", 302, "プレシア", 3.195, 2, -285.0, 139701);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10218, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 61, "2026/06/30 12:00:00", 1021801, 0.0, 2, "2030/01/01 14:59:59", 101, "ルイズマリー", 12.43, 3, -285.0, 139902);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10218, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 61, "2026/06/30 12:00:00", 1021802, 0.0, 2, "2030/01/01 14:59:59", 201, "クレジッタ", 6.35, 3, -285.0, 140001);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10219, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 61, "2026/07/31 12:00:00", 1021901, 0.0, 1, "2030/01/01 14:59:59", 101, "フブキ", 10.23, 5, -285.0, 140102);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (10219, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 61, "2026/07/31 12:00:00", 1021902, 0.0, 1, "2030/01/01 14:59:59", 201, "ヴァンピィ", 5.584, 2, -285.0, 140201);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 62, "2026/04/10 12:00:00", 2000001, 0.0, 1, "2030/01/01 14:59:59", 1, "カリン", 3.414, 2, -416.5, 190801);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, "ミッションをクリアして、\n報酬をゲットしましょう！", 62, "2026/04/10 12:00:00", 2000002, 0.0, 1, "2030/01/01 14:59:59", 2, "カリン", 3.099, 2, -416.5, 190801);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, "受け取ることができる\n報酬があるようです\n確認してみてください", 63, "2026/04/10 12:00:00", 2000003, 0.0, 1, "2030/01/01 14:59:59", 3, "カリン", 2.801, 2, -416.5, 190801);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, "報酬がもらえますよ！\nチェックしてみてください", 63, "2026/04/10 12:00:00", 2000004, 0.0, 2, "2030/01/01 14:59:59", 4, "カリン", 0.0, 2, -416.5, 190801);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 64, "2026/04/10 12:00:00", 2000005, 0.0, 2, "2030/01/01 14:59:59", 5, "カリン", 2.12, 1, -363.0, 190801);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 64, "2026/04/10 12:00:00", 2000006, 0.0, 1, "2030/01/01 14:59:59", 6, "カリン", 1.68, 2, -363.0, 190801);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 64, "2026/04/10 12:00:00", 2000007, 0.0, 2, "2030/01/01 14:59:59", 7, "カリン", 2.33, 1, -363.0, 190801);
